import subprocess

def run(html, args=[], stdin_bytes=None):
    if stdin_bytes is None and html is not None:
        stdin_bytes = html.encode()
    p = subprocess.run(["./executable"]+args, input=stdin_bytes, capture_output=True)
    return p.stdout, p.stderr, p.returncode

def t(html, args=[]):
    o,e,rc = run(html,args)
    print(f"IN: {html!r} ARGS:{args}")
    print(f" OUT:{o!r} ERR:{e!r} RC:{rc}\n")

# check "-domain" vs "--domain" - error says -domain without second dash, interesting.
# try single-dash variants
for args in [["-unknown"], ["-help"], ["-input", "x"], ["-domain=x"], ["-domain", "x"]]:
    o,e,rc = run("<p>x</p>", args)
    print(f"ARGS:{args} OUT:{o!r} ERR:{e!r} RC:{rc}")

# check = handling, bool flags with = ?
for args in [["--plugin-table=true"], ["--plugin-table=false"], ["--plugin-table="], ["--output-overwrite"]]:
    o,e,rc = run("<p>x</p>", args)
    try:
      print(f"ARGS:{args} OUT:{o.decode()!r} ERR:{e.decode()!r} RC:{rc}")
    except: print(args,o,e,rc)
PY
"}

