# ---------- HTML tree ----------
VOID_ELEMENTS = {"area","base","br","col","embed","hr","img","input","link","meta","param","source","track","wbr","basefont","bgsound","frame","isindex","keygen"}

SKIP_ELEMENTS = {"script","style","noscript","template","title","textarea","iframe"}  # content skipped (no output)
# Note: head is NOT skipped, but title inside head is skipped. svg/math etc. are transparent.

class Node:
    def __init__(self, tag=None, attrs=None, parent=None, is_text=False, text=""):
        self.tag = tag  # lower case, None for text/document
        self.attrs = attrs or {}
        self.children = []
        self.parent = parent
        self.is_text = is_text
        self.text = text  # for text nodes
        self.is_document = False

    def get_classes(self):
        c = self.attrs.get("class", "")
        if not c:
            return []
        return c.split()

    def get_id(self):
        return self.attrs.get("id", "")

    def __repr__(self):
        if self.is_text:
            return f"Text({self.text!r})"
        return f"Elem({self.tag}, {self.attrs}, {len(self.children)})"

class TreeBuilder(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = Node(tag="__document__")
        self.root.is_document = True
        self.stack = [self.root]
        # For handling mis-nested? Just push/pop

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        attr_dict = {}
        for k,v in attrs:
            k = k.lower()
            if v is None:
                v = ""
            attr_dict[k] = v
        parent = self.stack[-1]
        node = Node(tag=tag, attrs=attr_dict, parent=parent)
        parent.children.append(node)
        if tag in VOID_ELEMENTS:
            return
        # For skip elements, still need to push to skip content? Actually we still parse children but later skip rendering. So push.
        self.stack.append(node)

    def handle_startendtag(self, tag, attrs):
        tag = tag.lower()
        attr_dict = {}
        for k,v in attrs:
            k = k.lower()
            if v is None:
                v = ""
            attr_dict[k] = v
        parent = self.stack[-1]
        node = Node(tag=tag, attrs=attr_dict, parent=parent)
        parent.children.append(node)
        # void, no push

    def handle_endtag(self, tag):
        tag = tag.lower()
        # Find matching open in stack (search from top)
        for i in range(len(self.stack)-1, 0, -1):
            if self.stack[i].tag == tag:
                # pop up to i
                del self.stack[i:]
                break
        # else ignore (unmatched)

    def handle_data(self, data):
        # data already unescaped (convert_charrefs=True)
        # Keep as is (including whitespace), will handle later
        # But ignore if empty? Keep all, even whitespace, for pre handling?
        # We'll create text node even for whitespace (will be collapsed later unless in pre)
        parent = self.stack[-1]
        # If parent is skip element? Still add? No need, but we skip rendering anyway. Still add to keep structure? For skip, we ignore children during rendering, so no need to add. But to simplify, still add.
        node = Node(is_text=True, text=data, parent=parent)
        parent.children.append(node)

    def handle_comment(self, data):
        # ignore comments (do not add)
        pass

    def handle_decl(self, decl):
        pass

    def handle_pi(self, data):
        pass

def parse_html(html_str):
    builder = TreeBuilder()
    try:
        builder.feed(html_str)
        builder.close()
    except Exception:
        pass
    return builder.root

PYEOF
echo "tree appended"
"}

