# ---------- CSS selector matching ----------
# Simple CSS engine for include/exclude

def split_by_comma(sel):
    parts = []
    cur = ""
    depth_bracket = 0
    depth_paren = 0
    in_single = False
    in_double = False
    for ch in sel:
        if ch == "'" and not in_double:
            in_single = not in_single
            cur += ch
        elif ch == '"' and not in_single:
            in_double = not in_double
            cur += ch
        elif in_single or in_double:
            cur += ch
        elif ch == '[':
            depth_bracket += 1
            cur += ch
        elif ch == ']':
            depth_bracket -= 1
            cur += ch
        elif ch == '(':
            depth_paren += 1
            cur += ch
        elif ch == ')':
            depth_paren -= 1
            cur += ch
        elif ch == ',' and depth_bracket==0 and depth_paren==0:
            parts.append(cur.strip())
            cur = ""
        else:
            cur += ch
    if cur.strip() != "" or not parts:
        parts.append(cur.strip())
    return [p for p in parts if p != ""]

def parse_complex(complex_sel):
    # Returns list of (combinator, simple_str) where combinator is None for first, else ' ', '>', '+', '~'
    # Need to handle combinators with optional whitespace
    tokens = []
    cur = ""
    depth_bracket = 0
    depth_paren = 0
    in_single = False
    in_double = False
    combinator = None  # pending combinator for next simple
    i = 0
    n = len(complex_sel)
    result = []
    # We'll iterate and split on combinators not inside brackets/parens/quotes
    # First, normalize: replace multiple spaces? But need to track.
    # Approach: scan, when we see combinator char outside, flush cur.
    while i < n:
        ch = complex_sel[i]
        if ch == "'" and not in_double and depth_bracket==0 and depth_paren==0:
            # Actually quotes can be inside attr values, which are inside brackets. Handle generally.
            in_single = not in_single
            cur += ch
            i+=1
            continue
        if ch == '"' and not in_single:
            in_double = not in_double
            cur += ch
            i+=1
            continue
        if in_single or in_double:
            cur += ch
            i+=1
            continue
        if ch == '[':
            depth_bracket+=1
            cur+=ch
            i+=1
            continue
        if ch == ']':
            depth_bracket-=1
            cur+=ch
            i+=1
            continue
        if ch == '(':
            depth_paren+=1
            cur+=ch
            i+=1
            continue
        if ch == ')':
            depth_paren-=1
            cur+=ch
            i+=1
            continue
        if depth_bracket==0 and depth_paren==0:
            if ch in ('>', '+', '~'):
                # flush cur as simple
                s = cur.strip()
                if s != "":
                    result.append((combinator, s))
                    cur = ""
                combinator = ch
                i+=1
                # skip following whitespace
                while i<n and complex_sel[i].isspace():
                    i+=1
                continue
            elif ch.isspace():
                # whitespace combinator (descendant), but need to check if next non-space is combinator? Already handled.
                # Flush cur
                s = cur.strip()
                if s != "":
                    result.append((combinator, s))
                    cur = ""
                    combinator = ' '
                else:
                    # cur empty, keep existing combinator? If combinator already set (e.g., after >), don't overwrite with space.
                    if combinator is None:
                        combinator = ' '
